46		errConflict = errors.New("conflict")
47	)
48	
49	// Asset 为登记的设备资产，ID 即企业资产编号。
50	type Asset struct {
51		ID       string `json:"id"`
52		Name     string `json:"name"`
53		Location string `json:"location"`
54		Status   string `json:"status"`
55	}
56	
57	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
58	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
59	type Ticket struct {
60		ID           string `json:"id"`
61		AssetID      string `json:"asset_id"`
62		Description  string `json:"description"`
63		RequestID    string `json:"request_id"`
64		Status       string `json:"status"`
65		Result       string `json:"result,omitempty"`
66		CreatedAt    string `json:"created_at"`
67		ClosedAt     string `json:"closed_at,omitempty"`
68		CancelReason string `json:"cancel_reason,omitempty"`
69		CancelledAt  string `json:"cancelled_at,omitempty"`
70		Assignee     string `json:"assignee,omitempty"`
71		AssignedAt   string `json:"assigned_at,omitempty"`
72		AssignNote   string `json:"assign_note,omitempty"`
73	}
74	
75	// Event 为履历条目（报修/派工/关闭/取消/保养建立/保养完成/保养撤销/领用/退回/附件登记/附件撤销），Seq 决定操作发生顺序。
76	// From/To 仅派工履历使用：原负责人（首次派工为空，展示为“未派工”）与新负责人。
77	// Due/Done/Interval 仅保养履历使用：建立履历含首次到期日（Due）与间隔天数
78	// （Interval），完成履历含周期到期日（Due）与实际完成日（Done）。
79	// TargetSeq 仅保养撤销履历使用：被撤销的完成履历的全库序号；完成身份以此序号
80	// 标识，不能用到期日或报修请求标识代替。
81	// PartID/Quantity/WithdrawalID 仅备件履历使用：领用与退回履历都携带备件编号、
82	// 数量与所属领用编号；Content 分别为领用说明与退回理由。
83	// AttachmentID/Path 仅附件履历使用：登记与撤销履历都携带附件编号与保存的绝对
84	// 路径；Content 分别为附件说明与撤销理由。
85	type Event struct {
86		Seq          int       `json:"-"`
87		AssetID      string    `json:"-"`
88		TicketID     string    `json:"-"`
89		Kind         string    `json:"-"`
90		Content      string    `json:"-"`
91		From         string    `json:"-"`
92		To           string    `json:"-"`
93		Due          string    `json:"-"`
94		Done         string    `json:"-"`
95		Interval     int       `json:"-"`
96		TargetSeq    int       `json:"-"`
97		PartID       string    `json:"-"`
98		Quantity     int       `json:"-"`
99		WithdrawalID string    `json:"-"`
100		AttachmentID string    `json:"-"`
101		Path         string    `json:"-"`
102		Time         time.Time `json:"-"`
103	}
104	
105	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
106	type eventJSON struct {
107		Seq          int    `json:"seq"`
108		AssetID      string `json:"asset_id"`
109		TicketID     string `json:"ticket_id,omitempty"`
110		Kind         string `json:"kind"`
111		Content      string `json:"content"`
112		From         string `json:"from,omitempty"`
113		To           string `json:"to,omitempty"`
114		Due          string `json:"due,omitempty"`
115		Done         string `json:"done,omitempty"`
116		Interval     int    `json:"interval,omitempty"`
117		TargetSeq    int    `json:"target_seq,omitempty"`
118		PartID       string `json:"part_id,omitempty"`
119		Quantity     int    `json:"quantity,omitempty"`
120		WithdrawalID string `json:"withdrawal_id,omitempty"`
121		AttachmentID string `json:"attachment_id,omitempty"`
122		Path         string `json:"path,omitempty"`
123		Time         string `json:"time"`
124	}
125	
126	func (e Event) toJSON() eventJSON {
127		return eventJSON{
128			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
129			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
130			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
131			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
132			AttachmentID: e.AttachmentID, Path: e.Path,
133			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
134			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
135			// 在重新保存（含导入合并后的提交）时也不会被截断。
136			Time: e.Time.Format(time.RFC3339Nano),
137		}
138	}
139	
140	func (e eventJSON) toEvent() (Event, error) {
141		t, err := time.Parse(time.RFC3339, e.Time)
142		if err != nil {
143			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
144		}
145		return Event{
146			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
147			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
148			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
149			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
150			AttachmentID: e.AttachmentID, Path: e.Path,
151			Time: t,
152		}, nil
153	}
154	
155	// PartWithdrawal 为一笔备件领用记录，ID 即领用编号（同目录唯一、不复用）。
156	// 数量表示工单用量；Returned 为累计退回数量，净量 = Quantity - Returned。
157	// 工单关闭或取消后记录与净量保留，不清零。
158	type PartWithdrawal struct {
159		ID       string `json:"id"`
160		TicketID string `json:"ticket_id"`
161		AssetID  string `json:"asset_id"`
162		PartID   string `json:"part_id"`
163		Quantity int    `json:"quantity"`
164		Note     string `json:"note"`
165		Returned int    `json:"returned"`
166	}
167	
168	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
169	// 它既不是资产编号也不是工单编号。
170	type requestBinding struct {
171		RequestID   string `json:"request_id"`
172		AssetID     string `json:"asset_id"`
173		Description string `json:"description"`
174		TicketID    string `json:"ticket_id"`
175	}
176	
177	// Attachment 为工单本地资料附件的索引记录，ID 即附件编号（同目录唯一、不复用）。
178	// 只保存引用：Path 为登记时解析得到的绝对路径，工具不复制、不修改、不删除
179	// 资料文件本身。撤销后保留记录、路径、说明（Note）与撤销理由（RevokeReason），
180	// 已撤销编号不能恢复；工单终结不自动撤销附件。
181	type Attachment struct {
182		ID           string `json:"id"`
183		TicketID     string `json:"ticket_id"`
184		AssetID      string `json:"asset_id"`
185		Path         string `json:"path"`
186		Note         string `json:"note"`
187		Revoked      bool   `json:"revoked"`
188		RevokeReason string `json:"revoke_reason,omitempty"`
189	}
190	
191	// storeData 是一次成功写操作共同生效的完整业务数据。
192	type storeData struct {
193		Version       int               `json:"version"`
194		Assets        []*Asset          `json:"assets"`
195		Tickets       []*Ticket         `json:"tickets"`
196		Events        []Event           `json:"-"`
197		EventsJSON    []eventJSON       `json:"events"`
198		Requests      []requestBinding  `json:"requests"`
199		Plans         []*Plan           `json:"plans"`
200		Parts         []*PartWithdrawal `json:"parts"`
201		Attachments   []*Attachment     `json:"attachments"`
202		NextTicketSeq int               `json:"next_ticket_seq"`
203		NextPartSeq   int               `json:"next_part_seq"`
204		NextAttachSeq int               `json:"next_attach_seq"`
205	}
206	
207	type store struct {
208		dir  string
209		data *storeData
210		now  func() time.Time
211	}
212	
213	func newStoreData() *storeData {
214		return &storeData{
215			Version:       storeVersion,
216			Assets:        []*Asset{},
217			Tickets:       []*Ticket{},
218			Events:        []Event{},
219			EventsJSON:    []eventJSON{},
220			Requests:      []requestBinding{},
221			Plans:         []*Plan{},
222			Parts:         []*PartWithdrawal{},
223			Attachments:   []*Attachment{},
224			NextTicketSeq: 1,
225			NextPartSeq:   1,
226			NextAttachSeq: 1,
227		}
228	}
229	
230	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
231	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
232	func openStore(dir string) (*store, error) {
233		return loadStore(dir, true)
234	}
235	
236	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
237	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
238	func openSourceStore(dir string) (*store, error) {
239		return loadStore(dir, false)
240	}
241	
242	func loadStore(dir string, allowMissing bool) (*store, error) {
243		path := filepath.Join(dir, dataFileName)
244		raw, err := os.ReadFile(path)
245		if err != nil {
246			if errors.Is(err, os.ErrNotExist) {
247				if allowMissing {
248					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
249				}
250				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
251			}
252			return nil, fmt.Errorf("读取数据文件失败: %w", err)
253		}
254		if len(bytes.TrimSpace(raw)) == 0 {
255			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
256		}
257		var d storeData
258		if err := json.Unmarshal(raw, &d); err != nil {
259			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
260		}
261		if d.EventsJSON != nil {
262			d.Events = make([]Event, len(d.EventsJSON))
263			for i, ej := range d.EventsJSON {
264				ev, err := ej.toEvent()
265				if err != nil {
266					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
267				}
268				d.Events[i] = ev
269			}
270		}
271		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
272		if d.Plans == nil {
273			d.Plans = []*Plan{}
274		}
275		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
276		// 领用编号计数器从 1 开始。
277		if d.Parts == nil {
278			d.Parts = []*PartWithdrawal{}
279		}
280		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
281			d.NextPartSeq = 1
282		}
283		// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
284		// 附件编号计数器从 1 开始。
285		if d.Attachments == nil {
286			d.Attachments = []*Attachment{}
287		}
288		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
289			d.NextAttachSeq = 1
290		}
291		if err := validateData(&d); err != nil {
292			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
293		}
294		return &store{dir: dir, data: &d, now: time.Now}, nil
295	}
296	
297	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
298	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
299	func parseTicketSeq(id string) (int, bool) {
300		if !strings.HasPrefix(id, "T") {
301			return 0, false
302		}
303		n, err := strconv.Atoi(id[1:])
304		if err != nil || n < 1 {
305			return 0, false
306		}
307		if fmt.Sprintf("T%04d", n) != id {
308			return 0, false
309		}
310		return n, true
311	}
312	
313	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
314	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
315	func parsePartSeq(id string) (int, bool) {
316		if !strings.HasPrefix(id, "P") {
317			return 0, false
318		}
319		n, err := strconv.Atoi(id[1:])
320		if err != nil || n < 1 {
321			return 0, false
322		}
323		if fmt.Sprintf("P%04d", n) != id {
324			return 0, false
325		}
326		return n, true
327	}
328	
329	// parseAttachSeq 解析 A 加补零正整数序号形式的附件编号，返回序号。
330	// 编号必须与 fmt.Sprintf("A%04d", n)（n ≥ 1）完全一致，否则视为非法。
331	func parseAttachSeq(id string) (int, bool) {
332		if !strings.HasPrefix(id, "A") {
333			return 0, false
334		}
335		n, err := strconv.Atoi(id[1:])
336		if err != nil || n < 1 {
337			return 0, false
338		}
339		if fmt.Sprintf("A%04d", n) != id {
340			return 0, false
341		}
342		return n, true
343	}
344	
345	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
346	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
347	// 不做任何修复：不补字段、不重编号、不删除记录。
348	func validateData(d *storeData) error {
349		if d.Version != storeVersion {
350			return fmt.Errorf("不支持的数据版本 %d", d.Version)
351		}
352		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil || d.Attachments == nil {
353			return errors.New("缺少必要的数据段")
354		}
355		assets := map[string]*Asset{}
356		for _, a := range d.Assets {
357			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
358				return errors.New("数据矛盾：存在字段不完整的资产记录")
359			}
360			if a.Status != statusAvailable && a.Status != statusRepairing {
361				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
362			}
363			if assets[a.ID] != nil {
364				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
365			}
366			assets[a.ID] = a
367		}
368		tickets := map[string]*Ticket{}
369		maxTicketSeq := 0
370		for _, t := range d.Tickets {
371			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
372				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
373			}
374			n, ok := parseTicketSeq(t.ID)
375			if !ok {
376				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
377			}
378			if n > maxTicketSeq {
379				maxTicketSeq = n
380			}
381			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
382				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
383			}
384			if assets[t.AssetID] == nil {
385				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
386			}
387			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
388				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
389			}
390			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
391				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
392			}
393			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
394				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
395			}
396			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
397				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
398			}
399			if t.Assignee == "" {
400				if t.AssignedAt != "" || t.AssignNote != "" {
401					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
402				}
403			} else if t.AssignedAt == "" || t.AssignNote == "" {
404				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
405			}
406			if tickets[t.ID] != nil {
407				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
408			}
409			tickets[t.ID] = t
410		}
411		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
412		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
413			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
414				d.NextTicketSeq, maxTicketSeq)
415		}
416		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
417		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
418		// 履历序号重放时核对。
419		parts := map[string]*PartWithdrawal{}
420		maxPartSeq := 0
421		for _, p := range d.Parts {
422			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
423				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
424			}
425			n, ok := parsePartSeq(p.ID)
426			if !ok {
427				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
428			}
429			if n > maxPartSeq {
430				maxPartSeq = n
431			}
432			if p.Quantity < 1 {
433				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
434			}
435			if p.Returned < 0 || p.Returned > p.Quantity {
436				return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
437			}
438			t := tickets[p.TicketID]
439			if t == nil {
440				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
441			}
442			if t.AssetID != p.AssetID {
443				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
444					p.ID, p.AssetID, t.ID, t.AssetID)
445			}
446			if parts[p.ID] != nil {
447				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
448			}
449			parts[p.ID] = p
450		}
451		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
452		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
453			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
454				d.NextPartSeq, maxPartSeq)
455		}
456		// 附件索引记录：编号唯一且为 A 加补零正整数序号，归属存在的工单且资产归属
457		// 与工单一致，路径为绝对路径，说明非空；撤销状态与理由相互呼应。文件当前
458		// 是否可用不参与整库一致性校验；与履历的接续在下方按履历序号重放时核对。
459		attachments := map[string]*Attachment{}
460		maxAttachSeq := 0
461		for _, a := range d.Attachments {
462			if a == nil || a.ID == "" || a.TicketID == "" || a.AssetID == "" || a.Path == "" || a.Note == "" {
463				return errors.New("数据矛盾：存在字段不完整的附件记录")
464			}
465			n, ok := parseAttachSeq(a.ID)
466			if !ok {
467				return fmt.Errorf("计数器矛盾：附件编号 %q 不是 A 加补零正整数序号的形式", a.ID)
468			}
469			if n > maxAttachSeq {
470				maxAttachSeq = n
471			}
472			if !filepath.IsAbs(a.Path) {
473				return fmt.Errorf("数据矛盾：附件记录 %s 的路径 %q 不是绝对路径", a.ID, a.Path)
474			}
475			t := tickets[a.TicketID]
476			if t == nil {
477				return fmt.Errorf("数据矛盾：附件记录 %s 引用了不存在的工单 %s", a.ID, a.TicketID)
478			}
479			if t.AssetID != a.AssetID {
480				return fmt.Errorf("数据矛盾：附件记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
481					a.ID, a.AssetID, t.ID, t.AssetID)
482			}
483			if a.Revoked && a.RevokeReason == "" {
484				return fmt.Errorf("状态矛盾：已撤销附件 %s 缺少撤销理由", a.ID)
485			}
486			if !a.Revoked && a.RevokeReason != "" {
487				return fmt.Errorf("状态矛盾：有效附件 %s 不应带有撤销理由", a.ID)
488			}
489			if attachments[a.ID] != nil {
490				return fmt.Errorf("数据矛盾：附件编号 %s 重复", a.ID)
491			}
492			attachments[a.ID] = a
493		}
494		// 下一附件序号必须为正并大于全部已用序号（允许有间隔）。
495		if d.NextAttachSeq < 1 || d.NextAttachSeq <= maxAttachSeq {
496			return fmt.Errorf("计数器矛盾：下一附件序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
497				d.NextAttachSeq, maxAttachSeq)
498		}
499		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
500		boundReq := map[string]bool{}
501		boundTicket := map[string]bool{}
502		for _, r := range d.Requests {
503			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
504				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
505			}
506			if boundReq[r.RequestID] {
507				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
508			}
509			boundReq[r.RequestID] = true
510			t := tickets[r.TicketID]
511			if t == nil {
512				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
513			}
514			if t.RequestID != r.RequestID {
515				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
516					r.TicketID, t.RequestID, r.RequestID)
517			}
518			if r.AssetID != t.AssetID || r.Description != t.Description {
519				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
520					r.RequestID, t.ID)
521			}
522			boundTicket[r.TicketID] = true
523		}
524		for _, t := range d.Tickets {
525			if !boundTicket[t.ID] {
526				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
527			}
528		}
529		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
530		openCount := map[string]int{}
531		for _, t := range d.Tickets {
532			if t.Status == ticketOpen {
533				openCount[t.AssetID]++
534			}
535		}
536		for _, a := range d.Assets {
537			c := openCount[a.ID]
538			if c > 1 {
539				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
540			}
541			want := statusAvailable
542			if c == 1 {
543				want = statusRepairing
544			}
545			if a.Status != want {
546				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
547					a.ID, c, want, a.Status)
548			}
549		}
550		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
551		seenSeq := map[int]bool{}
552		reportSeq := map[string]int{}
553		closeSeq := map[string]int{}
554		cancelSeq := map[string]int{}
555		reportCount := map[string]int{}
556		closeCount := map[string]int{}
557		cancelCount := map[string]int{}
558		for i := range d.Events {
559			e := &d.Events[i]
560			if e.Seq < 1 {
561				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
562			}
563			if seenSeq[e.Seq] {
564				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
565			}
566			seenSeq[e.Seq] = true
567			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
568				return errors.New("履历矛盾：存在字段不完整的履历记录")
569			}
570			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone || e.Kind == eventPlanRevoke {
571				// 保养履历：不属于任何工单，不携带派工字段；日期与间隔在此核对，
572				// 建立、完成及撤销链的接续在下方按序号重放时核对。
573				if e.TicketID != "" || e.From != "" || e.To != "" {
574					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
575				}
576				if e.Kind == eventPlanRevoke {
577					// 撤销履历：内容即撤销理由（非空已检查），仅携带目标完成履历序号。
578					if e.Due != "" || e.Done != "" || e.Interval != 0 {
579						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录不应带有到期日、完成日或间隔天数", e.Seq)
580					}
581					if e.TargetSeq < 1 {
582						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录目标完成履历序号须为正整数", e.Seq)
583					}
584					continue
585				}
586				if e.TargetSeq != 0 {
587					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有目标完成履历序号", e.Seq, e.Kind)
588				}
589				due, err := parseDate(e.Due)
590				if err != nil {
591					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
592				}
593				if e.Kind == eventPlanCreate {
594					if e.Done != "" {
595						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
596					}
597					if e.Interval < 1 {
598						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
599					}
600				} else {
601					if e.Interval != 0 {
602						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
603					}
604					done, err := parseDate(e.Done)
605					if err != nil {
606						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
607					}
608					if done < due {
609						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
610					}
611				}
612				continue
613			}
614			if e.TicketID == "" {
615				return errors.New("履历矛盾：存在字段不完整的履历记录")
616			}
617			if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 {
618				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
619			}
620			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
621				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
622			}
623			if e.Kind == eventAssign {
624				if e.To == "" {
625					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
626				}
627				if e.From == e.To {
628					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
629				}
630			}
631			// 附件字段仅附件履历携带；附件履历不携带备件字段。
632			if e.Kind != eventAttach && e.Kind != eventAttachRevoke && (e.AttachmentID != "" || e.Path != "") {
633				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有附件编号或路径", e.Seq, e.Kind)
634			}
635			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) &&
636				(e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "") {
637				return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件字段", e.Seq, e.Kind)
638			}
639			t := tickets[e.TicketID]
640			if t == nil || assets[e.AssetID] == nil {
641				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
642			}
643			if e.AssetID != t.AssetID {
644				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
645					e.Seq, e.AssetID, t.ID, t.AssetID)
646			}
647			switch e.Kind {
648			case eventReport:
649				if e.Content != t.Description {
650					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
651				}
652				reportCount[t.ID]++
653				reportSeq[t.ID] = e.Seq
654			case eventClose:
655				if e.Content != t.Result {
656					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
657				}
658				closeCount[t.ID]++
659				closeSeq[t.ID] = e.Seq
660			case eventCancel:
661				if e.Content != t.CancelReason {
662					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
663				}
664				cancelCount[t.ID]++
665				cancelSeq[t.ID] = e.Seq
666			case eventAssign:
667				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
668				// 在下方按序号重放时核对。
669			case eventPartWithdraw, eventPartReturn:
670				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
671				// 与领用记录的接续及累计退回在下方按序号重放时核对。
672				if e.PartID == "" || e.WithdrawalID == "" {
673					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
674				}
675				if e.Quantity < 1 {
676					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
677				}
678				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
679					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
680						e.Seq, e.WithdrawalID)
681				}
682			case eventAttach, eventAttachRevoke:
683				// 内容即附件说明或撤销理由（非空已检查）；附件字段在此核对，
684				// 与附件记录的接续及登记、撤销顺序在下方按序号重放时核对。
685				if e.AttachmentID == "" || e.Path == "" {
686					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少附件编号或路径", e.Seq, e.Kind)
687				}
688				if _, ok := parseAttachSeq(e.AttachmentID); !ok {
689					return fmt.Errorf("履历矛盾：履历序号 %d 的附件编号 %q 不是 A 加补零正整数序号的形式",
690						e.Seq, e.AttachmentID)
691				}
692				if !filepath.IsAbs(e.Path) {
693					return fmt.Errorf("履历矛盾：履历序号 %d 的附件路径 %q 不是绝对路径", e.Seq, e.Path)
694				}
695			default:
696				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
697			}
698		}
699		for _, t := range d.Tickets {
700			if reportCount[t.ID] != 1 {
701				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
702			}
703			if t.Status == ticketClosed {
704				if closeCount[t.ID] != 1 {
705					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
706				}
707				if closeSeq[t.ID] <= reportSeq[t.ID] {
708					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
709						t.ID, closeSeq[t.ID], reportSeq[t.ID])
710				}
711			} else if closeCount[t.ID] != 0 {
712				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
713			}
714			if t.Status == ticketCancelled {
715				if cancelCount[t.ID] != 1 {
716					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
717				}
718				if cancelSeq[t.ID] <= reportSeq[t.ID] {
719					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
720						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
721				}
722			} else if cancelCount[t.ID] != 0 {
723				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
724			}
725		}
726		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
727		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
728		sorted := make([]Event, len(d.Events))
729		copy(sorted, d.Events)
730		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
731		derivedTicket := map[string]string{}
732		derivedOpen := map[string]string{}
733		derivedAssignee := map[string]string{}
734		derivedNote := map[string]string{}
735		withdrawSeq := map[string]int{}
736		derivedReturned := map[string]int{}
737		attachRegSeq := map[string]int{}
738		attachRevokeSeq := map[string]int{}
739		for _, e := range sorted {
740			switch e.Kind {
741			case eventReport:
742				if derivedTicket[e.TicketID] != "" {
743					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
744				}
745				if prev := derivedOpen[e.AssetID]; prev != "" {
746					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
747						e.AssetID, prev, e.TicketID)
748				}
749				derivedTicket[e.TicketID] = ticketOpen
750				derivedOpen[e.AssetID] = e.TicketID
751			case eventAssign:
752				if derivedTicket[e.TicketID] != ticketOpen {
753					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
754				}
755				if e.From != derivedAssignee[e.TicketID] {
756					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
757						e.TicketID, e.Seq, e.From)
758				}
759				derivedAssignee[e.TicketID] = e.To
760				derivedNote[e.TicketID] = e.Content
761			case eventClose:
762				if derivedTicket[e.TicketID] != ticketOpen {
763					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
764				}
765				derivedTicket[e.TicketID] = ticketClosed
766				delete(derivedOpen, e.AssetID)
767			case eventCancel:
768				if derivedTicket[e.TicketID] != ticketOpen {
769					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
770				}
771				derivedTicket[e.TicketID] = ticketCancelled
772				delete(derivedOpen, e.AssetID)
773			case eventPartWithdraw:
774				// 领用须在报修之后、终结之前；履历与领用记录的业务字段必须一致。
775				if derivedTicket[e.TicketID] != ticketOpen {
776					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现领用履历（序号 %d）",
777						e.TicketID, e.Seq)
778				}
779				p := parts[e.WithdrawalID]
780				if p == nil {
781					return fmt.Errorf("履历矛盾：领用履历（序号 %d）引用了不存在的领用记录 %s",
782						e.Seq, e.WithdrawalID)
783				}
784				if withdrawSeq[p.ID] != 0 {
785					return fmt.Errorf("履历矛盾：领用记录 %s 有多条领用履历", p.ID)
786				}
787				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID ||
788					p.Quantity != e.Quantity || p.Note != e.Content {
789					return fmt.Errorf("履历矛盾：领用履历（序号 %d）与领用记录 %s 的工单、资产、备件、数量或说明不一致",
790						e.Seq, p.ID)
791				}
792				withdrawSeq[p.ID] = e.Seq
793			case eventPartReturn:
794				// 退回须在报修之后、终结之前，且指向先前已领用的记录；
795				// 累计退回不得超过该笔原数量。
796				if derivedTicket[e.TicketID] != ticketOpen {
797					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现退回履历（序号 %d）",
798						e.TicketID, e.Seq)
799				}
800				p := parts[e.WithdrawalID]
801				if p == nil {
802					return fmt.Errorf("履历矛盾：退回履历（序号 %d）引用了不存在的领用记录 %s",
803						e.Seq, e.WithdrawalID)
804				}
805				if withdrawSeq[p.ID] == 0 {
806					return fmt.Errorf("履历矛盾：退回履历（序号 %d）出现在领用记录 %s 的领用履历之前",
807						e.Seq, p.ID)
808				}
809				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID {
810					return fmt.Errorf("履历矛盾：退回履历（序号 %d）与领用记录 %s 的工单、资产或备件不一致",
811						e.Seq, p.ID)
812				}
813				// 逐步核对累计退回不超过原数量：先做不会溢出的减法比较再累加。
814				// 直接相加可能整数溢出回绕，即使回绕后的累计恰好等于保存值，
815				// 实际超额的履历也必须拒绝。
816				if e.Quantity > p.Quantity-derivedReturned[p.ID] {
817					return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回在履历序号 %d 处超过原数量 %d",
818						p.ID, e.Seq, p.Quantity)
819				}
820				derivedReturned[p.ID] += e.Quantity
821			case eventAttach:
822				// 登记须在报修之后；未关闭、已关闭或已取消工单均可补充资料。
823				// 履历与附件记录的业务字段必须一致。
824				if derivedTicket[e.TicketID] == "" {
825					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件登记履历（序号 %d）",
826						e.TicketID, e.Seq)
827				}
828				a := attachments[e.AttachmentID]
829				if a == nil {
830					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）引用了不存在的附件记录 %s",
831						e.Seq, e.AttachmentID)
832				}
833				if attachRegSeq[a.ID] != 0 {
834					return fmt.Errorf("履历矛盾：附件记录 %s 有多条登记履历", a.ID)
835				}
836				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.Note != e.Content {
837					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）与附件记录 %s 的工单、资产、路径或说明不一致",
838						e.Seq, a.ID)
839				}
840				attachRegSeq[a.ID] = e.Seq
841			case eventAttachRevoke:
842				// 撤销须在登记之后，且每个附件至多撤销一次；
843				// 履历与附件记录的业务字段必须一致。
844				if derivedTicket[e.TicketID] == "" {
845					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件撤销履历（序号 %d）",
846						e.TicketID, e.Seq)
847				}
848				a := attachments[e.AttachmentID]
849				if a == nil {
850					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）引用了不存在的附件记录 %s",
851						e.Seq, e.AttachmentID)
852				}
853				if attachRegSeq[a.ID] == 0 {
854					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）出现在附件记录 %s 的登记履历之前",
855						e.Seq, a.ID)
856				}
857				if attachRevokeSeq[a.ID] != 0 {
858					return fmt.Errorf("履历矛盾：附件记录 %s 有多条撤销履历", a.ID)
859				}
860				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.RevokeReason != e.Content {
861					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）与附件记录 %s 的工单、资产、路径或撤销理由不一致",
862						e.Seq, a.ID)
863				}
864				attachRevokeSeq[a.ID] = e.Seq
865			}
866		}
867		for _, t := range d.Tickets {
868			if derivedTicket[t.ID] != t.Status {
869				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
870					t.ID, derivedTicket[t.ID], t.Status)
871			}
872			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
873			if derivedAssignee[t.ID] != t.Assignee {
874				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
875					t.ID, derivedAssignee[t.ID], t.Assignee)
876			}
877			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
878				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
879			}
880		}
881		// 每笔领用记录恰有一条领用履历；按履历重放得到的累计退回须与保存值一致。
882		for _, p := range d.Parts {
883			if withdrawSeq[p.ID] == 0 {
884				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
885			}
886			if derivedReturned[p.ID] != p.Returned {
887				return fmt.Errorf("备件数量矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
888					p.ID, derivedReturned[p.ID], p.Returned)
889			}
890		}
891		// 每条附件记录恰有一条登记履历、至多一条撤销履历；记录的撤销状态须与
892		// 是否存在撤销履历一致。
893		for _, a := range d.Attachments {
894			if attachRegSeq[a.ID] == 0 {
895				return fmt.Errorf("履历矛盾：附件记录 %s 缺少对应的登记履历", a.ID)
896			}
897			if revoked := attachRevokeSeq[a.ID] != 0; revoked != a.Revoked {
898				return fmt.Errorf("状态矛盾：附件记录 %s 保存的撤销状态与履历不符", a.ID)
899			}
900		}
901		for _, a := range d.Assets {
902			want := statusAvailable
903			if derivedOpen[a.ID] != "" {
904				want = statusRepairing
905			}
906			if a.Status != want {
907				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
908					a.ID, want, a.Status)
909			}
910		}
911		// 保养计划：归属存在的资产、每项资产最多一个、日期有效、间隔为正整数。
912		plans := map[string]*Plan{}
913		for _, p := range d.Plans {
914			if p == nil || p.AssetID == "" || p.Content == "" {
915				return errors.New("数据矛盾：存在字段不完整的保养计划")
916			}
917			if assets[p.AssetID] == nil {
918				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
919			}
920			if plans[p.AssetID] != nil {
921				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
922			}
923			if _, err := parseDate(p.FirstDue); err != nil {
924				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
925			}
926			if p.IntervalDays < 1 {
927				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
928			}
929			if _, err := parseDate(p.NextDue); err != nil {
930				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
931			}
932			plans[p.AssetID] = p
933		}
934		// 保养履历链：每个计划恰有一条建立履历（内容、首次到期日、间隔与计划一致），
935		// 完成履历按序号接续（周期到期日须等于当时下一到期日，完成日不早于它），
936		// 撤销履历须引用先前同资产、未撤销且当时最新有效的完成，并把下一到期日恢复
937		// 为该完成的周期到期日；由履历推出的下一到期日须与计划保存的一致。
938		// 没有计划的资产不得有保养履历。
939		maintCreate := map[string]int{}
940		derivedDue := map[string]string{}
941		doneSeqs := map[string][]int{}
942		doneDue := map[string]map[int]string{}
943		revokedDone := map[int]bool{}
944		for _, e := range sorted {
945			if e.Kind != eventPlanCreate && e.Kind != eventPlanDone && e.Kind != eventPlanRevoke {
946				continue
947			}
948			p := plans[e.AssetID]
949			if p == nil {
950				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
951			}
952			if e.Kind == eventPlanCreate {
953				if maintCreate[e.AssetID] != 0 {
954					return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", e.AssetID)
955				}
956				maintCreate[e.AssetID] = e.Seq
957				if e.Content != p.Content || e.Due != p.FirstDue || e.Interval != p.IntervalDays {
958					return fmt.Errorf("履历矛盾：资产 %s 的保养建立履历与计划内容、首次到期日或间隔不一致", e.AssetID)
959				}
960				derivedDue[e.AssetID] = e.Due
961				continue
962			}
963			if maintCreate[e.AssetID] == 0 {
964				return fmt.Errorf("履历矛盾：资产 %s 的%s履历（序号 %d）出现在建立履历之前", e.AssetID, e.Kind, e.Seq)
965			}
966			if e.Kind == eventPlanRevoke {
967				// 目标须为先前同资产的完成履历（更晚序号的完成此时尚未出现），
968				// 未撤销且为当时最新有效；撤销后下一到期日恢复为其周期到期日。
969				due, ok := doneDue[e.AssetID][e.TargetSeq]
970				if !ok {
971					return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历",
972						e.Seq, e.TargetSeq, e.AssetID)
973				}
974				if revokedDone[e.TargetSeq] {
975					return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", e.TargetSeq, e.Seq)
976				}
977				latest := 0
978				for _, seq := range doneSeqs[e.AssetID] {
979					if !revokedDone[seq] {
980						latest = seq
981					}
982				}
983				if latest != e.TargetSeq {
984					return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）",
985						e.Seq, e.TargetSeq, latest)
986				}
987				revokedDone[e.TargetSeq] = true
988				derivedDue[e.AssetID] = due
989				continue
990			}
991			if e.Due != derivedDue[e.AssetID] {
992				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
993					e.AssetID, e.Seq, e.Due, derivedDue[e.AssetID])
994			}
995			first, _ := parseDate(p.FirstDue)
996			done, _ := parseDate(e.Done)
997			next, ok := nextDueAfter(first, int64(p.IntervalDays), done)
998			if !ok {
999				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
1000					e.AssetID, e.Seq)
1001			}
1002			derivedDue[e.AssetID] = formatDate(next)
1003			doneSeqs[e.AssetID] = append(doneSeqs[e.AssetID], e.Seq)
1004			if doneDue[e.AssetID] == nil {
1005				doneDue[e.AssetID] = map[int]string{}
1006			}
1007			doneDue[e.AssetID][e.Seq] = e.Due
1008		}
1009		for _, p := range d.Plans {
1010			if maintCreate[p.AssetID] == 0 {
1011				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
1012			}
1013			if derivedDue[p.AssetID] != p.NextDue {
1014				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
1015					p.AssetID, derivedDue[p.AssetID], p.NextDue)
1016			}
1017		}
1018		return nil
1019	}
1020	
1021	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1022	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1023	// 保持不变，不留下部分业务变化。
1024	func (s *store) save() error {
1025		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1026		for i, e := range s.data.Events {
1027			s.data.EventsJSON[i] = e.toJSON()
1028		}
1029		if err := validateData(s.data); err != nil {
1030			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1031		}
1032		var buf bytes.Buffer
1033		enc := json.NewEncoder(&buf)
1034		enc.SetIndent("", "  ")
1035		if err := enc.Encode(s.data); err != nil {
1036			return fmt.Errorf("编码数据失败: %w", err)
1037		}
1038		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1039			return fmt.Errorf("创建数据目录失败: %w", err)
1040		}
1041		path := filepath.Join(s.dir, dataFileName)
1042		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1043		if err != nil {
1044			return fmt.Errorf("创建临时数据文件失败: %w", err)
1045		}
1046		tmpName := tmp.Name()
1047		abort := func(err error) error {
1048			_ = tmp.Close()
1049			_ = os.Remove(tmpName)
1050			return err
1051		}
1052		if _, err := tmp.Write(buf.Bytes()); err != nil {
1053			abort(nil)
1054			return fmt.Errorf("写入数据失败: %w", err)
1055		}
1056		if err := tmp.Sync(); err != nil {
1057			abort(nil)
1058			return fmt.Errorf("写入数据失败: %w", err)
1059		}
1060		if err := tmp.Close(); err != nil {
1061			_ = os.Remove(tmpName)
1062			return fmt.Errorf("写入数据失败: %w", err)
1063		}
1064		if err := os.Rename(tmpName, path); err != nil {
1065			_ = os.Remove(tmpName)
1066			return fmt.Errorf("保存数据失败: %w", err)
1067		}
1068		return nil
1069	}
1070	
1071	func (s *store) findAsset(id string) *Asset {
1072		for _, a := range s.data.Assets {
1073			if a.ID == id {
1074				return a
1075			}
1076		}
1077		return nil
1078	}
1079	
1080	func (s *store) findTicket(id string) *Ticket {
1081		for _, t := range s.data.Tickets {
1082			if t.ID == id {
1083				return t
1084			}
1085		}
1086		return nil
1087	}
1088	
1089	func (s *store) findRequest(requestID string) *requestBinding {
1090		for i := range s.data.Requests {
1091			if s.data.Requests[i].RequestID == requestID {
1092				return &s.data.Requests[i]
1093			}
1094		}
1095		return nil
1096	}
1097	
1098	func (s *store) openTicketOf(assetID string) *Ticket {
1099		for _, t := range s.data.Tickets {
1100			if t.AssetID == assetID && t.Status == ticketOpen {
1101				return t
1102			}
1103		}
1104		return nil
1105	}
1106	
1107	func (s *store) eventsOf(assetID string) []Event {
1108		out := make([]Event, 0)
1109		for _, e := range s.data.Events {
1110			if e.AssetID == assetID {
1111				out = append(out, e)
1112			}
1113		}
1114		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
1115		return out
1116	}
1117	
1118	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1119	func (s *store) nextEventSeq() (int, error) {
1120		maxSeq := 0
1121		for _, e := range s.data.Events {
1122			if e.Seq > maxSeq {
1123				maxSeq = e.Seq
1124			}
1125		}
1126		if maxSeq == math.MaxInt {
1127			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1128		}
1129		return maxSeq + 1, nil
1130	}
1131	
1132	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
1133	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
1134	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
1135		s.data.Events = append(s.data.Events, Event{
1136			Seq:      seq,
1137			AssetID:  assetID,
1138			TicketID: ticketID,
1139			Kind:     kind,
1140			Content:  content,
1141			From:     from,
1142			To:       to,
1143			Time:     s.now(),
1144		})
1145	}
1146	
1147	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
1148		if s.findAsset(id) != nil {
1149			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
1150		}
1151		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
1152		s.data.Assets = append(s.data.Assets, a)
1153		return a, nil
1154	}
1155	
1156	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1157	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1158	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1159		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1160		// 资产或描述不同 => 拒绝。
1161		if r := s.findRequest(requestID); r != nil {
1162			if r.AssetID != assetID || r.Description != description {
1163				return nil, false, fmt.Errorf(
1164					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1165					errConflict, requestID, r.AssetID)
1166			}
1167			t := s.findTicket(r.TicketID)
1168			if t == nil {
1169				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1170			}
1171			return t, true, nil
1172		}
1173	
1174		asset := s.findAsset(assetID)
1175		if asset == nil {
1176			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1177		}
1178		if t := s.openTicketOf(assetID); t != nil {
1179			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1180		}
1181		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1182		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1183		seq := s.data.NextTicketSeq
1184		if seq < 1 || seq == math.MaxInt {
1185			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1186		}
1187		eventSeq, err := s.nextEventSeq()
1188		if err != nil {
1189			return nil, false, err
1190		}
1191		t := &Ticket{
1192			ID:          fmt.Sprintf("T%04d", seq),
1193			AssetID:     assetID,
1194			Description: description,
1195			RequestID:   requestID,
1196			Status:      ticketOpen,
1197			CreatedAt:   s.now().Format(time.RFC3339),
1198		}
1199		s.data.NextTicketSeq = seq + 1
1200		s.data.Tickets = append(s.data.Tickets, t)
1201		s.data.Requests = append(s.data.Requests, requestBinding{
1202			RequestID:   requestID,
1203			AssetID:     assetID,
1204			Description: description,
1205			TicketID:    t.ID,
1206		})
1207		asset.Status = statusRepairing
1208		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1209		return t, false, nil
1210	}
1211	
1212	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1213	// 失败路径不修改任何业务数据。
1214	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1215		t := s.findTicket(ticketID)
1216		if t == nil {
1217			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1218		}
1219		if t.Status == ticketCancelled {
1220			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1221		}
1222		if t.Status != ticketOpen {
1223			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1224		}
1225		asset := s.findAsset(t.AssetID)
1226		if asset == nil {
1227			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1228		}
1229		eventSeq, err := s.nextEventSeq()
1230		if err != nil {
1231			return nil, nil, err
1232		}
1233		t.Status = ticketClosed
1234		t.Result = result
1235		t.ClosedAt = s.now().Format(time.RFC3339)
1236		asset.Status = statusAvailable
1237		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1238		return t, asset, nil
1239	}
1240	
1241	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1242	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1243	// 失败路径不修改任何业务数据。
1244	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1245		t := s.findTicket(ticketID)
1246		if t == nil {
1247			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1248		}
1249		if t.Status == ticketCancelled {
1250			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1251		}
1252		if t.Status == ticketClosed {
1253			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1254		}
1255		asset := s.findAsset(t.AssetID)
1256		if asset == nil {
1257			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1258		}
1259		eventSeq, err := s.nextEventSeq()
1260		if err != nil {
1261			return nil, nil, err
1262		}
1263		t.Status = ticketCancelled
1264		t.CancelReason = reason
1265		t.CancelledAt = s.now().Format(time.RFC3339)
1266		asset.Status = statusAvailable
1267		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1268		return t, asset, nil
1269	}
1270	
1271	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1272	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1273	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1274	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1275	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1276	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1277		t := s.findTicket(ticketID)
1278		if t == nil {
1279			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1280		}
1281		if t.Status == ticketClosed {
1282			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1283		}
1284		if t.Status == ticketCancelled {
1285			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1286		}
1287		if assignee == "" {
1288			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1289		}
1290		if note == "" {
1291			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1292		}
1293		if t.Assignee == assignee {
1294			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1295				errConflict, ticketID, assignee)
1296		}
1297		eventSeq, err := s.nextEventSeq()
1298		if err != nil {
1299			return nil, err
1300		}
1301		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1302		t.Assignee = assignee
1303		t.AssignedAt = s.now().Format(time.RFC3339)
1304		t.AssignNote = note
1305		return t, nil
1306	}
