49	}
50	
51	// ticketRemap 记录一张工单的原编号与新编号。
52	type ticketRemap struct {
53		OldID string
54		NewID string
55	}
56	
57	// partRemap 记录一笔备件领用的原领用编号与新领用编号。
58	type partRemap struct {
59		OldID string
60		NewID string
61	}
62	
63	// attachRemap 记录一条附件索引的原附件编号与新附件编号。
64	type attachRemap struct {
65		OldID string
66		NewID string
67	}
68	
69	// completionRemap 记录一条保养完成履历的原全库序号与新全库序号。
70	type completionRemap struct {
71		OldSeq int
72		NewSeq int
73	}
74	
75	// importOutcome 为一次成功导入的结果摘要，用于输出。
76	type importOutcome struct {
77		assetIDs    []string
78		tickets     []ticketRemap
79		parts       []partRemap
80		attachments []attachRemap
81		completions []completionRemap
