85	func cmdImport(args []string, w io.Writer) error {
86		var opts cmdOptions
87		var sourceDir string
88		var assetIDs stringListFlag
89		fs := newFlagSet("import", &opts)
90		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
91		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
92		if err := parseFlags(fs, args); err != nil {
93			return err
94		}
95		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
96			return err
97		}
98		if len(assetIDs) == 0 {
99			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
100		}
101		for _, id := range assetIDs {
102			if id == "" {
103				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
104			}
105		}
106	
107		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
108		if err != nil {
109			return err
110		}
111		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
112		if outcome.plans > 0 {
113			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
114		}
115		if len(outcome.tickets) == 0 {
116			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
117		} else {
118			fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
119			for _, m := range outcome.tickets {
120				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
121			}
122		}
123		if len(outcome.parts) > 0 {
124			fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
125			for _, m := range outcome.parts {
126				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
127			}
128		}
129		if len(outcome.attachments) > 0 {
130			fmt.Fprintln(w, "附件编号映射（原编号 -> 新编号）:")
131			for _, m := range outcome.attachments {
132				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
133			}
134		}
135		if len(outcome.completions) > 0 {
136			fmt.Fprintln(w, "完成履历序号映射（原序号 -> 新序号）:")
137			for _, m := range outcome.completions {
138				fmt.Fprintf(w, "%d -> %d\n", m.OldSeq, m.NewSeq)
139			}
140		}
141		return nil
142	}
143	
144	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
145	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
146	// 两边原文件字节保持不变。
147	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
148		srcAbs, err := filepath.Abs(sourceDir)
149		if err != nil {
150			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
151		}
152		dstAbs, err := filepath.Abs(targetDir)
153		if err != nil {
154			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
155		}
156		if srcAbs == dstAbs {
157			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
158		}
159		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
160		srcPath := filepath.Join(srcAbs, dataFileName)
161		dstPath := filepath.Join(dstAbs, dataFileName)
162		if fi1, err1 := os.Stat(srcPath); err1 == nil {
163			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
164				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
165			}
166		}
167	
168		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
169		src, err := openSourceStore(srcAbs)
170		if err != nil {
171			return nil, err
172		}
173		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
174		dst, err := openStore(dstAbs)
175		if err != nil {
176			return nil, err
177		}
178		outcome, err := dst.mergeImport(src, assetIDs)
179		if err != nil {
180			return nil, err
181		}
182		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
183		if err := dst.save(); err != nil {
184			return nil, err
185		}
186		return outcome, nil
187	}
188	
189	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
190	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
191	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
192		// 重复编号按一项处理，保持首次出现的顺序。
193		selected := map[string]bool{}
194		ids := make([]string, 0, len(assetIDs))
195		for _, id := range assetIDs {
196			if !selected[id] {
197				selected[id] = true
198				ids = append(ids, id)
199			}
200		}
201		// 所选资产必须存在于源，且编号在目标中不存在。
202		assets := make([]*Asset, 0, len(ids))
203		for _, id := range ids {
204			a := src.findAsset(id)
205			if a == nil {
206				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
207			}
208			if s.findAsset(id) != nil {
209				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
210			}
211			assets = append(assets, a)
212		}
213		// 所选资产的全部工单，按源工单序号升序重新分配编号。
214		tickets := make([]*Ticket, 0)
215		for _, t := range src.data.Tickets {
216			if selected[t.AssetID] {
217				tickets = append(tickets, t)
218			}
219		}
220		sort.SliceStable(tickets, func(i, j int) bool {
221			ni, _ := parseTicketSeq(tickets[i].ID)
222			nj, _ := parseTicketSeq(tickets[j].ID)
223			return ni < nj
224		})
225		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
226		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
227			return nil, fmt.Errorf(
228				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
229				errConflict, s.data.NextTicketSeq, len(tickets))
230		}
231		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
232		srcReqByTicket := map[string]*requestBinding{}
233		for i := range src.data.Requests {
234			r := &src.data.Requests[i]
235			srcReqByTicket[r.TicketID] = r
236		}
237		for _, t := range tickets {
238			r := srcReqByTicket[t.ID]
239			if r == nil {
240				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
241			}
242			if s.findRequest(r.RequestID) != nil {
243				return nil, fmt.Errorf(
244					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
245			}
246		}
247		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
248		events := make([]Event, 0)
249		for _, e := range src.data.Events {
250			if selected[e.AssetID] {
251				events = append(events, e)
252			}
253		}
254		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
255		maxSeq := 0
256		for _, e := range s.data.Events {
257			if e.Seq > maxSeq {
258				maxSeq = e.Seq
259			}
260		}
261		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
262		if len(events) > math.MaxInt-maxSeq {
263			return nil, fmt.Errorf(
264				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
265				errConflict, maxSeq, len(events))
266		}
267		// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
268		// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
269		srcTicketIDs := map[string]bool{}
270		for _, t := range tickets {
271			srcTicketIDs[t.ID] = true
272		}
273		srcWithdrawSeq := map[string]int{}
274		for _, e := range src.data.Events {
275			if e.Kind == eventPartWithdraw {
276				srcWithdrawSeq[e.WithdrawalID] = e.Seq
277			}
278		}
279		parts := make([]*PartWithdrawal, 0)
280		for _, p := range src.data.Parts {
281			if srcTicketIDs[p.TicketID] {
282				parts = append(parts, p)
283			}
284		}
285		sort.SliceStable(parts, func(i, j int) bool {
286			return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
287		})
288		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
289		if len(parts) > math.MaxInt-s.data.NextPartSeq {
290			return nil, fmt.Errorf(
291				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
292				errConflict, s.data.NextPartSeq, len(parts))
293		}
294		// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
295		// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
296		// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
297		// 导入失败。
298		srcAttachRegSeq := map[string]int{}
299		for _, e := range src.data.Events {
300			if e.Kind == eventAttach {
301				srcAttachRegSeq[e.AttachmentID] = e.Seq
302			}
303		}
304		attachments := make([]*Attachment, 0)
305		for _, a := range src.data.Attachments {
306			if srcTicketIDs[a.TicketID] {
307				attachments = append(attachments, a)
308			}
309		}
310		sort.SliceStable(attachments, func(i, j int) bool {
311			return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
312		})
313		// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
314		if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
315			return nil, fmt.Errorf(
316				"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
317				errConflict, s.data.NextAttachSeq, len(attachments))
318		}
319	
320		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
321		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
322		for _, a := range assets {
323			na := *a
324			s.data.Assets = append(s.data.Assets, &na)
325		}
326		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
327		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
328		planCount := 0
329		for _, p := range src.data.Plans {
330			if selected[p.AssetID] {
331				np := *p
332				s.data.Plans = append(s.data.Plans, &np)
333				planCount++
334			}
335		}
336		outcome := &importOutcome{assetIDs: ids, plans: planCount}
337		remap := map[string]string{}
338		next := s.data.NextTicketSeq
339		for _, t := range tickets {
340			nt := *t
341			nt.ID = fmt.Sprintf("T%04d", next)
342			remap[t.ID] = nt.ID
343			s.data.Tickets = append(s.data.Tickets, &nt)
344			r := srcReqByTicket[t.ID]
345			s.data.Requests = append(s.data.Requests, requestBinding{
346				RequestID:   r.RequestID,
347				AssetID:     r.AssetID,
348				Description: r.Description,
349				TicketID:    nt.ID,
350			})
351			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
352			next++
353		}
354		s.data.NextTicketSeq = next
355		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
356		// 数量、累计退回与说明等业务信息原样保留。
357		partIDs := map[string]string{}
358		nextPart := s.data.NextPartSeq
359		for _, p := range parts {
360			np := *p
361			np.ID = fmt.Sprintf("P%04d", nextPart)
362			np.TicketID = remap[p.TicketID]
363			partIDs[p.ID] = np.ID
364			s.data.Parts = append(s.data.Parts, &np)
365			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
366			nextPart++
367		}
368		s.data.NextPartSeq = nextPart
369		// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
370		// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
371		attachIDs := map[string]string{}
372		nextAttach := s.data.NextAttachSeq
373		for _, a := range attachments {
374			na := *a
375			na.ID = fmt.Sprintf("A%04d", nextAttach)
376			na.TicketID = remap[a.TicketID]
377			attachIDs[a.ID] = na.ID
378			s.data.Attachments = append(s.data.Attachments, &na)
379			outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
380			nextAttach++
381		}
382		s.data.NextAttachSeq = nextAttach
383		seq := maxSeq
384		seqRemap := map[int]int{}
385		for _, e := range events {
386			seq++
387			ne := e
388			ne.Seq = seq
389			ne.TicketID = remap[e.TicketID]
390			ne.WithdrawalID = partIDs[e.WithdrawalID]
391			ne.AttachmentID = attachIDs[e.AttachmentID]
392			if e.Kind == eventPlanRevoke {
393				// 撤销履历的目标完成序号随履历重编号同步替换：目标在源序号顺序中
394				// 先于撤销出现（源台账已通过一致性检查），此处必然已有映射。
395				ne.TargetSeq = seqRemap[e.TargetSeq]
396			}
397			seqRemap[e.Seq] = seq
398			if e.Kind == eventPlanDone {
399				outcome.completions = append(outcome.completions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
400			}
401			s.data.Events = append(s.data.Events, ne)
402		}
403		return outcome, nil
404	}
