152			t.Fatalf("未知工单应失败，得到 %v", err)
153		}
154	}
155	
156	func TestCancelLifecycle(t *testing.T) {
157		s := newTestStore(t)
158		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
159			t.Fatal(err)
160		}
161		tk, _, err := s.report("EQ-1", "卡纸", "req-1")
162		if err != nil {
163			t.Fatal(err)
164		}
165	
166		// 未知工单取消失败，不产生任何变化。
167		if _, _, err := s.cancelTicket("T9999", "误报"); !errors.Is(err, errNotFound) {
168			t.Fatalf("未知工单取消应失败，得到 %v", err)
169		}
170		if got := len(s.eventsOf("EQ-1")); got != 1 {
171			t.Fatalf("失败的取消不应产生履历，履历数 = %d", got)
172		}
173	
174		// 取消未关闭工单：进入已取消终态，保存理由与时间，资产恢复可用。
175		cancelled, asset, err := s.cancelTicket(tk.ID, "误报，设备实际正常")
176		if err != nil {
177			t.Fatalf("cancelTicket: %v", err)
178		}
179		if cancelled.Status != ticketCancelled || cancelled.CancelReason != "误报，设备实际正常" ||
180			cancelled.CancelledAt == "" {
181			t.Fatalf("取消后工单状态异常: %+v", cancelled)
182		}
183		if cancelled.Result != "" || cancelled.ClosedAt != "" {
184			t.Fatal("取消不应填写维修结果或关闭时间")
185		}
186		if asset.Status != statusAvailable {
187			t.Fatalf("取消后资产状态 = %q", asset.Status)
188		}
189		if got := s.openTicketOf("EQ-1"); got != nil {
190			t.Fatalf("取消后不应有未关闭工单，得到 %v", got)
191		}
192	
193		// 已取消工单不能再次取消，也不能关闭。
194		if _, _, err := s.cancelTicket(tk.ID, "再次取消"); !errors.Is(err, errConflict) {
195			t.Fatalf("重复取消应失败，得到 %v", err)
196		}
197		if _, _, err := s.closeTicket(tk.ID, "结果"); !errors.Is(err, errConflict) {
198			t.Fatalf("已取消工单关闭应失败，得到 %v", err)
199		}
200	
201		// 资产可用后可用新请求开新工单，编号不复用。
202		tk2, replay, err := s.report("EQ-1", "无法开机", "req-2")
203		if err != nil || replay || tk2.ID != "T0002" {
204			t.Fatalf("取消后新报修应开出 T0002: %v replay=%v err=%v", tk2, replay, err)
205		}
206	
207		// 旧请求重放返回原工单的已取消状态，不产生记录，不影响新单。
208		old, replay, err := s.report("EQ-1", "卡纸", "req-1")
209		if err != nil || !replay || old.ID != "T0001" || old.Status != ticketCancelled {
210			t.Fatalf("重放应返回已取消的 T0001: %v replay=%v err=%v", old, replay, err)
211		}
212		if len(s.data.Tickets) != 2 || len(s.data.Requests) != 2 {
213			t.Fatalf("重放不应增加记录: tickets=%d requests=%d", len(s.data.Tickets), len(s.data.Requests))
214		}
215		if got := s.openTicketOf("EQ-1"); got == nil || got.ID != "T0002" {
216			t.Fatalf("新工单 T0002 应仍为未关闭，得到 %v", got)
217		}
218	
219		// 已关闭工单不能取消。
220		if _, _, err := s.closeTicket(tk2.ID, "已更换电源"); err != nil {
221			t.Fatal(err)
222		}
223		if _, _, err := s.cancelTicket(tk2.ID, "理由"); !errors.Is(err, errConflict) {
224			t.Fatalf("已关闭工单取消应失败，得到 %v", err)
225		}
226	
227		// 履历：取消事件按序号排列，内容为取消理由。
228		events := s.eventsOf("EQ-1")
229		if len(events) != 4 {
230			t.Fatalf("履历条数 = %d，想得到 4", len(events))
231		}
232		if events[0].Kind != eventReport || events[0].TicketID != "T0001" ||
233			events[1].Kind != eventCancel || events[1].TicketID != "T0001" ||
